import React, {useEffect, useState} from 'react';
import api from '../api';
import Sidebar from "../components/Sidebar";
import Profile from "./Profile";
import Loans from './Loans';
import './Dashboard.css';

export default function Dashboard() {
    const [me, setMe] = useState(null);
    const [view, setView] = useState('home');
    const [user, setUser] = useState(null);
    const [funds, setFunds] = useState([]);

    useEffect(() => {
        api.get('/user/').then(res => setUser(res.data))
            .catch(err => console.error(err));

        api.get('/funds/')
            .then(res => {
                if (Array.isArray(res.data)) {
                    setFunds(res.data);
                }
            })
            .catch(err => console.error(err));

        api.get(`/funds/${fundId}/members/`)
            .then(res => setMembers(res.data))
            .catch(err => console.error(err));
    }, [fundId]);


    const renderContent = () => {
        switch (view) {
            case 'profile' :
                return <Profile user={user}/>
            case 'loans' :
                return <Loans/>
            default :
                return (
                    <div>
                        <h2>صندوق‌ها</h2>
                        {funds.length === 0 && <p>شما عضو هیچ صندوقی نیستید</p>}
                        {funds.map(f => (
                            <div key={f.id} className="fund-card">
                                <h3>{f.name}</h3>
                                <p>موجودی: {f.balance.toLocaleString()} تومان</p>
                                <p>شارژ ماهانه: {f.monthly_charge}</p>
                                <button>درخواست وام</button>
                            </div>
                        ))}
                    </div>
                );
        }
    };

    return (
        <div className="user-dashboard">
            <Sidebar onSelect={setView} isUser/>
            <div className="main-content">
                {renderContent()}
            </div>
            <div>
                <h2>اعضای صندوق</h2>
                <ul>
                    {members.map(m => (
                        <li key={m.id}>
                            {m.username}
                            <button onClick={() => removeMember(m.id)}>حذف</button>
                        </li>
                    ))}
                </ul>
                <div>
                    <input
                        type="number"
                        placeholder="User ID"
                        value={newUserId}
                        onChange={e => setNewUserId(e.target.value)}
                    />
                    <button onClick={addMember}>افزودن</button>
                </div>
            </div>
        </div>
    );
}
